export type SlotResult = { ok: true; minutes: number } | { ok: false; code: string };

export function line(r: SlotResult): string {
  return 'OK, ' + r.minutes + ' minutes';
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { line } from '../src/slot.ts';

test('ok', () => assert.equal(line({ ok: true, minutes: 120 }), 'OK, 120 minutes'));
test('failed', () => assert.equal(line({ ok: false, code: 'OFF_GRID' }), 'REFUSED: OFF_GRID'));

