export type SlotCode = 'OFF_GRID' | 'END_BEFORE_START' | 'OUTSIDE_HOURS' | 'TOO_LONG';

export function message(code: SlotCode): string {
  if (code === 'OFF_GRID') return 'Use the 30-minute grid.';
  if (code === 'TOO_LONG') return 'At most 4 hours.';
  return 'unknown error';
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { message } from '../src/message.ts';

test('off grid', () => assert.equal(message('OFF_GRID'), 'Use the 30-minute grid.'));
test('end before start', () => assert.equal(message('END_BEFORE_START'), 'The end is before the start.'));
test('outside hours', () => assert.equal(message('OUTSIDE_HOURS'), 'The lab is open 07:00-21:00.'));
test('too long', () => assert.equal(message('TOO_LONG'), 'At most 4 hours.'));

