export function parseSeats(text: string): number {
  const n = Number(text);
  if (!Number.isInteger(n) || n < 1) throw new RangeError('bad seats: ' + text);
  return n;
}

export function safe(text: string): string {
  try {
    return 'seats: ' + parseSeats(text);
  } catch (e) {
    return e.message;
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { safe } from '../src/safe.ts';

test('ok', () => assert.equal(safe('30'), 'seats: 30'));
test('bad', () => assert.equal(safe('x'), 'bad seats: x'));

